from flask import Flask


def test_index_route(app: Flask) -> None:
    client = app.test_client()
    response = client.get("/")
    assert response.status_code == 200


if __name__ == "__main__":
    app = Flask(__name__)

    @app.route("/")
    def index():
        return "OK"

    test_index_route(app)
    print("OK: / returned 200")
